import { useState } from "react";
import "../styles/Sidebar.css";

export default function Sidebar() {
    const [conversations, setConversations] = useState([
        { id: 1, title: "Welcome Chat", lastUpdated: "10:00 AM" },
        { id: 2, title: "Practice English", lastUpdated: "Yesterday" },
    ]);
    const [activeId, setActiveId] = useState(1);

    const handleNewChat = () => {
        const newId = Date.now();
        const newConvo = {
            id: newId,
            title: "New Chat",
            lastUpdated: new Date().toLocaleTimeString([], {
                hour: "2-digit",
                minute: "2-digit",
            }),
        };
        setConversations((prev) => [newConvo, ...prev]);
        setActiveId(newId);
    };

    return (
        <div className="sidebar">
            <div className="sidebar-header">
                <h2>💬 Conversations</h2>
                <button className="new-chat-btn" onClick={handleNewChat}>
                    ➕
                </button>
            </div>

            <ul className="conversation-list">
                {conversations.map((c) => (
                    <li
                        key={c.id}
                        className={`conversation-item ${activeId === c.id ? "active" : ""
                            }`}
                        onClick={() => setActiveId(c.id)}
                    >
                        <div className="conversation-title">{c.title}</div>
                        <div className="conversation-time">{c.lastUpdated}</div>
                    </li>
                ))}
            </ul>
        </div>
    );
}
